use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/coalesce-query176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-coalesce-query176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn walk(dir:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(dir).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,out)}else{out.push(p)}}}
fn main(){let base=Path::new(R).join("archive-review");assert!(!base.exists());fs::create_dir(&base).unwrap();let mut checks=BTreeMap::new();
 for name in["source","workflow","receipts","codegen"]{let out=base.join(name);fs::create_dir(&out).unwrap();assert!(Command::new("tar").arg("-xzf").arg(Path::new(D).join(format!("artifacts/{name}.tar.gz"))).arg("-C").arg(&out).status().unwrap().success());let mut files=vec![];walk(&out,&mut files);let count=files.len();for f in files{let relative=f.strip_prefix(&out).unwrap();assert_eq!(hash(&f),hash(Path::new(R).join(relative)));let s=relative.to_string_lossy();assert!(!s.ends_with("-sdk")&&!s.ends_with(".data")&&!s.ends_with(".rlib")&&!s.ends_with(".b2q")&&!s.ends_with(".a1q"));}checks.insert(name,count);}
 assert_eq!(checks["source"],177);let readme=fs::read_to_string(Path::new(D).join("README.md")).unwrap();let mut links=0;for s in readme.split("](").skip(1){let target=s.split(')').next().unwrap();if !target.starts_with("http")&&target!="SHA256SUMS"{assert!(Path::new(D).join(target).is_file())}links+=1;}
 let result=json!({"passed":true,"archive_files_byte_exact":checks,"README_links":links,"private_arrays_binaries_libraries_perf_not_published":true,"source_snapshot_files":177,"all_raw449commands_previously_independently_reviewed":true,"new_proofs":0,"production_changed":false,"gate":false});fs::write(Path::new(D).join("artifacts/publication-review.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");let _:Option<Value>=None;}
